<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Branch Cashbook</title><style>body{font:15px Arial;background:#f4f6fa;color:#172b43}.wrap{max-width:1200px;margin:30px auto;padding:0 15px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.card{background:#fff;padding:20px;border-radius:12px;margin:14px 0;overflow:auto}.value{font-size:24px;font-weight:bold;margin-top:10px}input,select{padding:10px;border:1px solid #ccd5df;border-radius:6px;margin:4px}button,a{background:#173d65;color:#fff;padding:9px 13px;border:0;border-radius:7px;text-decoration:none;cursor:pointer}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:11px;border-bottom:1px solid #eee;font-size:13px}.in{color:#18794e}.out{color:#b42318}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><h1>Branch Cashbook</h1><p><a href="{{ route('dashboard') }}">Dashboard</a> <a href="{{ route('expenses.index') }}">Expenses</a> <a href="{{ route('reports.index') }}">Reports</a></p>@if(session('success'))<p class="in">{{ session('success') }}</p>@endif<div class="card"><form method="GET"><label>From <input type="date" name="from" value="{{ $from }}"></label><label>To <input type="date" name="to" value="{{ $to }}"></label>@if(auth()->user()->hasRole('owner'))<select name="branch_id"><option value="">All branches</option>@foreach($branches as $b)<option value="{{ $b->id }}" @selected((string)$branchId===(string)$b->id)>{{ $b->name }}</option>@endforeach</select>@endif<button>Filter</button></form></div><div class="grid"><div class="card"><div>Cash In</div><div class="value in">PKR {{ number_format($cashIn,2) }}</div></div><div class="card"><div>Cash Out</div><div class="value out">PKR {{ number_format($cashOut,2) }}</div></div><div class="card"><div>Net Movement</div><div class="value">PKR {{ number_format($cashIn-$cashOut,2) }}</div></div></div>@if(auth()->user()->hasPermission('expenses.manage'))<div class="card"><h2>Manual Cash Adjustment</h2><form method="POST" action="{{ route('cashbook.store') }}">@csrf @if(auth()->user()->hasRole('owner'))<select name="branch_id" required><option value="">Branch</option>@foreach($branches as $b)<option value="{{ $b->id }}">{{ $b->name }}</option>@endforeach</select>@else<input type="hidden" name="branch_id" value="{{ auth()->user()->branch_id }}">@endif<select name="direction"><option value="in">Cash In</option><option value="out">Cash Out</option></select><input type="number" min=".01" step=".01" name="amount" required placeholder="Amount PKR"><input name="description" required placeholder="Reason / description"><button>Record Adjustment</button></form></div>@endif<div class="card"><h2>Cash Transactions</h2><table><tr><th>Date</th><th>Branch</th><th>Direction</th><th>Type</th><th>Description</th><th>Method</th><th>Amount PKR</th><th>Recorded By</th></tr>@forelse($transactions as $t)<tr><td>{{ $t->transacted_at->format('d M Y H:i') }}</td><td>{{ $t->branch->name }}</td><td class="{{ $t->direction }}">{{ strtoupper($t->direction) }}</td><td>{{ str_replace('_',' ',$t->type) }}</td><td>{{ $t->description }}</td><td>{{ $t->payment_method }}</td><td>{{ number_format($t->amount,2) }}</td><td>{{ $t->creator?->name ?? 'System' }}</td></tr>@empty<tr><td colspan="8">No cash transactions for this period.</td></tr>@endforelse</table>{{ $transactions->links() }}</div></main></body></html>
